#!/usr/bin/env sh
# One-command demo (macOS/Linux/WSL). Run from anywhere:  sh scripts/demo.sh   [--with-frontend]
# Needs Docker. Everything shown is SIMULATED data. Not for a real deployment (the API runs with ENVIRONMENT=development).
# Steps: create .env.demo once (random infrastructure secrets, git-ignored) -> start db, redis and the API (migrations
# run on start) -> seed (scripts/demo_seed.py, DEMO_MODE=true) -> print URLs and the demo logins.
# The three demo passwords are generated by the seed, printed ONCE and kept nowhere else.
# Reset to a fresh demo:  docker compose --env-file .env.demo -f docker-compose.yml -f docker-compose.demo.yml down -v
set -eu
cd "$(dirname "$0")/.."

secret() { LC_ALL=C tr -dc 'A-HJ-NP-Za-km-z2-9' </dev/urandom | head -c "$1"; }

ENV_FILE=.env.demo
if [ ! -f "$ENV_FILE" ]; then
  # Infrastructure secrets only (database, cache, token signing). The demo USER passwords are not stored here.
  umask 077
  {
    echo "POSTGRES_PASSWORD=$(secret 32)"
    echo "REDIS_PASSWORD=$(secret 32)"
    echo "JWT_SECRET_KEY=$(secret 64)"
  } > "$ENV_FILE"
  echo "Created $ENV_FILE (random local secrets; git-ignored)."
fi

compose() { docker compose --env-file "$ENV_FILE" -f docker-compose.yml -f docker-compose.demo.yml "$@"; }

echo "Starting database, cache and API (first run builds the image and can take several minutes)..."
compose up -d --build --wait db redis backend

echo "Seeding simulated demo data..."
compose run --rm demo-seed

echo
echo "API:       http://localhost:8000   (health: http://localhost:8000/healthz)"
echo "Frontend:  http://localhost:8080   (start it with: cd twin-stream-insight-main && npm ci && npm run dev)"
echo "Sign in with one of the demo logins printed above (viewer / operator / admin). All data is simulated."

if [ "${1:-}" = "--with-frontend" ]; then
  cd twin-stream-insight-main
  npm ci
  npm run dev
fi
